import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BfWdyVj4.js";const u=JSON.parse('{"title":"Voice and personalities","description":"","frontmatter":{},"headers":[],"relativePath":"features/voice.md","filePath":"features/voice.md","lastUpdated":1795530846000}'),i={name:"features/voice.md"};function n(r,e,l,h,d,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="voice-and-personalities" tabindex="-1">Voice and personalities <a class="header-anchor" href="#voice-and-personalities" aria-label="Permalink to &quot;Voice and personalities&quot;">​</a></h1><h2 id="the-personalities" tabindex="-1">The personalities <a class="header-anchor" href="#the-personalities" aria-label="Permalink to &quot;The personalities&quot;">​</a></h2><p>Each personality changes the look, the on-screen words, the voice, and how the assistant talks:</p><ul><li><strong>Verity</strong> (the default)</li><li><strong>Falsity</strong></li><li><strong>Lovity</strong></li><li><strong>Frog</strong></li></ul><p>The display&#39;s personality is picked in the welcome or Settings, and the assistant is told it with every request.</p><h2 id="making-your-own" tabindex="-1">Making your own <a class="header-anchor" href="#making-your-own" aria-label="Permalink to &quot;Making your own&quot;">​</a></h2><p>The admin page&#39;s <strong>Personalities</strong> tab makes new ones. Describe a character (&quot;a sleepy cloud who loves weather facts&quot;) and Claude writes everything a personality needs:</p><ul><li>how it talks, for the assistant;</li><li>the display&#39;s colours, and its words on screen (the greeting, and what it says while listening, thinking or when something goes wrong);</li><li>a Piper voice and a pitch;</li><li>an animated SVG face, with every mood the built-in faces have: waiting (blinking), listening, thinking, speaking and confused, plus happy, sad and tired.</li></ul><p>The preview has buttons for each mood. Change anything by hand, or ask for something different (&quot;make the face rounder, and the voice less shouty&quot;) and Claude redraws it. <strong>Save</strong> adds it for every display (they pick it up with the shared settings, within a minute) and makes its Home Assistant pipeline, <code>Frog Hub · &lt;Name&gt;</code>, copied from Frog&#39;s with the new voice. That needs the shared Home Assistant token to belong to an HA admin; without it, the personality still works with the usual voice.</p><p>Claude is reached through <code>claude -p</code> on your subscription (with no tools, MCP servers, hooks or saved session) when Claude Code is installed, and the Anthropic API with <code>ANTHROPIC_API_KEY</code> otherwise. Making one takes a minute or two.</p><p>Safety, since it&#39;s for children&#39;s displays:</p><ul><li>Claude is told to keep it friendly and suitable for young children, and to make the nearest friendly version of anything that isn&#39;t.</li><li>The face is rebuilt from an allowlist on the server: only shapes, gradients, text and CSS animations survive. No scripts, event handlers, links or outside files. Displays only ever show it as an image, where SVGs can&#39;t run anything anyway.</li><li>The assistant is told who a custom personality is with each request, and the rules for looking after the children still come first, whatever it says. Grown-ups see and can edit all of it before saving.</li></ul><h2 id="how-a-conversation-goes" tabindex="-1">How a conversation goes <a class="header-anchor" href="#how-a-conversation-goes" aria-label="Permalink to &quot;How a conversation goes&quot;">​</a></h2><ol><li><strong>Wake word and speech-to-text.</strong> The display streams 16 kHz audio to Home Assistant in one pipeline run (<code>wake_word</code> → <code>stt</code>), with the personality&#39;s pipeline, <code>Frog Hub · &lt;Personality&gt;</code>: openWakeWord listens for &quot;hey jarvis&quot;, then Whisper writes down what was said.</li><li><strong>The answer.</strong> The display asks the assistant (<code>POST /api/ask</code>) with the text, the personality, who it&#39;s for and the room&#39;s devices. The reply is text, and maybe <a href="/features/devices-music">room actions</a>, a card for the screen or a follow-up question (then it keeps listening).</li><li><strong>Speech.</strong> A second pipeline run (<code>tts</code> only) speaks it with the personality&#39;s Piper voice, played back at the personality&#39;s pitch.</li></ol><p>Quick room commands (&quot;lights off&quot;, &quot;next song&quot;, &quot;volume 30&quot;) are handled on the display itself in a few milliseconds, without asking the assistant.</p><h2 id="long-answers" tabindex="-1">Long answers <a class="header-anchor" href="#long-answers" aria-label="Permalink to &quot;Long answers&quot;">​</a></h2><p>Long answers are fine: the assistant puts the main point first. A reply over 350 characters goes on a card, and only the first part is spoken, followed by &quot;The rest is on the screen.&quot;</p><h2 id="cards-on-the-screen" tabindex="-1">Cards on the screen <a class="header-anchor" href="#cards-on-the-screen" aria-label="Permalink to &quot;Cards on the screen&quot;">​</a></h2><p>The assistant can put a card on the screen with its reply (<code>show_on_screen</code>): a title, an emoji or picture, text and lists, such as a recipe&#39;s ingredients, how to spell a word or a times table. Cards scroll, and the full-screen button makes them fill the screen.</p><h2 id="thinking-harder" tabindex="-1">Thinking harder <a class="header-anchor" href="#thinking-harder" aria-label="Permalink to &quot;Thinking harder&quot;">​</a></h2><p>The assistant runs on Haiku, which is quick. For what needs real thought (homework, a careful explanation, planning) it can call <code>think_harder</code>, which hands that one question to a bigger model and puts the answer in its own words.</p><ul><li>The Claude Code brain runs a one-shot, locked-down <code>claude -p</code> (no tools, no settings, no saved session; given 25 s).</li><li>The API brain asks the bigger model again with the whole conversation. On an OpenAI-compatible API (no Anthropic key, or when Claude fails) that&#39;s <code>FROGHUB_FALLBACK_BIG_MODEL</code>, a bigger model at the same API; without it, the fallback answers everything itself.</li></ul><p><code>FROGHUB_BIG_MODEL</code> picks the bigger model (by default Sonnet; <code>none</code> turns it off). On a subscription, Sonnet uses up the limits faster than Haiku.</p><h2 id="a-fresh-start" tabindex="-1">A fresh start <a class="header-anchor" href="#a-fresh-start" aria-label="Permalink to &quot;A fresh start&quot;">​</a></h2><p>The Claude Code brain&#39;s conversation is cleared (<code>/clear</code>) after 30 quiet minutes with no request open (<code>FROGHUB_CLEAR_AFTER</code>, in minutes; 0 never), so old chat doesn&#39;t pile up; its memory files stay. The API brain only ever keeps the last six exchanges of a conversation, which the display starts afresh after 5 quiet minutes.</p><h2 id="adding-a-personality" tabindex="-1">Adding a personality <a class="header-anchor" href="#adding-a-personality" aria-label="Permalink to &quot;Adding a personality&quot;">​</a></h2><p>See <a href="/developers/#adding-a-personality">Working on Frog Hub</a>.</p>',27)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
